src={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
out={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# coordinates local crop 0-index rows/cols. enumerate rotations/reflections
transforms={
'id':lambda r,c:(r,c),
'flipH':lambda r,c:(r,9-c),
'flipV':lambda r,c:(8-r,c),
'rot180':lambda r,c:(8-r,9-c),
'T':lambda r,c:(c,r),
'rot90cw':lambda r,c:(c,8-r),
'rot90ccw':lambda r,c:(9-c,r),
'antiT':lambda r,c:(9-c,8-r),
}
for n,f in transforms.items():
  ss={f(*p) for p in src}
  print(n, ss==out, len(ss&out), sorted(ss-out)[:4],sorted(out-ss)[:4])
